34	function Ensure-Directory {
35	    param([Parameter(Mandatory = $true)][string]$Path)
36	
37	    if (-not (Test-Path -LiteralPath $Path -PathType Container)) {
38	        New-Item -ItemType Directory -Force -Path $Path | Out-Null
