42	function Write-WatchLog {
43	    param([Parameter(Mandatory = $true)][string]$Message)
44	
45	    $stamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
46	    $logDir = Split-Path -Parent $LogPath
47	    if (-not [string]::IsNullOrWhiteSpace($logDir)) {
48	        Ensure-Directory -Path $logDir
49	    }
50	
51	    Add-Content -LiteralPath $LogPath -Encoding UTF8 -Value "[$stamp] $Message"
52	}
