54	function Get-RegistryLastWriteUtc {
55	    if (Test-Path -LiteralPath $ObsidianConfigPath -PathType Leaf) {
56	        return (Get-Item -LiteralPath $ObsidianConfigPath).LastWriteTimeUtc
57	    }
58	
59	    return $null
60	}
