62	function Invoke-ObsidianPluginInstall {
63	    if (-not (Test-Path -LiteralPath $InstallerScript -PathType Leaf)) {
64	        Write-WatchLog -Message "Installer script not found: $InstallerScript"
65	        return
66	    }
67	
68	    try {
69	        Write-WatchLog -Message "Running installer: $InstallerScript"
70	        $output = & $InstallerScript 2>&1
71	        foreach ($line in $output) {
72	            Write-WatchLog -Message ([string]$line)
73	        }
74	        Write-WatchLog -Message 'Installer finished.'
75	    }
76	    catch {
77	        Write-WatchLog -Message "Installer failed: $($_.Exception.Message)"
78	    }
79	}
80	
81	$createdNew = $false
82	$mutex = New-Object System.Threading.Mutex($true, 'Local\ObsidianPluginAutoInstall', [ref]$createdNew)
83	if (-not $createdNew) {
84	    Write-WatchLog -Message 'Watcher is already running; exiting this instance.'
85	    exit 0
86	}
87	
88	try {
89	    Write-WatchLog -Message "Plugin watcher started. PollSeconds=$PollSeconds; IntervalSeconds=$IntervalSeconds"
90	    $lastKnownWrite = Get-RegistryLastWriteUtc
91	    $lastRunUtc = [datetime]::MinValue
92	
93	    Invoke-ObsidianPluginInstall
94	    $lastRunUtc = (Get-Date).ToUniversalTime()
95	    $lastKnownWrite = Get-RegistryLastWriteUtc
96	
97	    while ($true) {
98	        Start-Sleep -Seconds $PollSeconds
99	
100	        $nowUtc = (Get-Date).ToUniversalTime()
101	        $currentWrite = Get-RegistryLastWriteUtc
102	        $changed = ($null -ne $currentWrite -and $null -ne $lastKnownWrite -and $currentWrite -ne $lastKnownWrite) -or ($null -ne $currentWrite -and $null -eq $lastKnownWrite)
103	        $due = (($nowUtc - $lastRunUtc).TotalSeconds -ge $IntervalSeconds)
104	
105	        if ($changed -or $due) {
106	            if ($changed) {
107	                Write-WatchLog -Message "Obsidian vault registry changed: $ObsidianConfigPath"
108	            }
109	            Invoke-ObsidianPluginInstall
110	            $lastRunUtc = (Get-Date).ToUniversalTime()
111	            $lastKnownWrite = Get-RegistryLastWriteUtc
112	        }
113	    }
114	}
115	finally {
116	    if ($null -ne $mutex) {
117	        $mutex.ReleaseMutex() | Out-Null
118	        $mutex.Dispose()
119	    }
120	}
