160	function Assert-PluginSource {
161	    param(
162	        [Parameter(Mandatory = $true)][string]$PluginId,
163	        [Parameter(Mandatory = $true)][string]$Path
164	    )
165	
166	    if (-not (Test-Path -LiteralPath $Path -PathType Container)) {
167	        throw "Plugin source directory not found for ${PluginId}: $Path"
168	    }
