206	function Install-PluginsForVault {
207	    param(
208	        [Parameter(Mandatory = $true)][string]$VaultPath,
209	        [Parameter(Mandatory = $true)][object[]]$Plugins
210	    )
211	
212	    $obsidianDir = Join-Path $VaultPath '.obsidian'
213	    $pluginsDir = Join-Path $obsidianDir 'plugins'
214	    $communityPluginsPath = Join-Path $obsidianDir 'community-plugins.json'
215	
216	    Ensure-Directory -Path $obsidianDir
217	    Ensure-Directory -Path $pluginsDir
218	
219	    $enabledPlugins = Get-EnabledCommunityPlugins -Path $communityPluginsPath
220	    $changed = $false
221	    $installedCount = 0
222	
223	    foreach ($plugin in $Plugins) {
224	        if ([string]::IsNullOrWhiteSpace($plugin.id)) {
225	            Write-InstallLog -Message "Skipped plugin definition without id."
226	            continue
227	        }
228	
229	        $sourceDir = Join-Path $PluginSourceRoot $plugin.id
230	        $manifestId = Assert-PluginSource -PluginId $plugin.id -Path $sourceDir
231	        $targetPluginDir = Join-Path $pluginsDir $manifestId
232	
233	        Copy-PluginSource -SourceDir $sourceDir -TargetDir $targetPluginDir
234	        $installedCount++
235	
236	        if ($enabledPlugins -notcontains $manifestId) {
237	            $enabledPlugins = @($enabledPlugins) + $manifestId
238	            $changed = $true
239	        }
240	    }
241	
242	    if ($changed) {
243	        Set-EnabledCommunityPlugins -Path $communityPluginsPath -Plugins $enabledPlugins
244	        Write-InstallLog -Message "Installed/enabled plugins for vault: $VaultPath; installed=$installedCount; enabledTotal=$($enabledPlugins.Count)"
245	    }
246	    else {
247	        Write-InstallLog -Message "Plugins already installed/enabled for vault: $VaultPath; installed=$installedCount; enabledTotal=$($enabledPlugins.Count)"
248	    }
249	}
250	
251	$pluginDefinitions = Get-PluginDefinitions
252	if ($pluginDefinitions.Count -eq 0) {
253	    Write-InstallLog -Message "No plugin definitions found."
254	    exit 1
255	}
256	
257	if (-not (Test-Path -LiteralPath $ObsidianConfigPath -PathType Leaf)) {
258	    Write-InstallLog -Message "Obsidian vault registry not found: $ObsidianConfigPath"
259	    exit 0
260	}
261	
262	$config = Get-JsonFileValue -Path $ObsidianConfigPath -DefaultValue $null
263	if ($null -eq $config) {
264	    Write-InstallLog -Message "Unable to read Obsidian vault registry: $ObsidianConfigPath"
265	    exit 1
266	}
267	
268	$vaultsProperty = $config.PSObject.Properties['vaults']
269	if ($null -eq $vaultsProperty -or $null -eq $vaultsProperty.Value) {
270	    Write-InstallLog -Message "No vaults found in Obsidian registry: $ObsidianConfigPath"
271	    exit 0
272	}
273	
274	$processed = 0
275	$skipped = 0
276	foreach ($vaultProperty in $vaultsProperty.Value.PSObject.Properties) {
277	    $pathProperty = $vaultProperty.Value.PSObject.Properties['path']
278	    if ($null -eq $pathProperty -or [string]::IsNullOrWhiteSpace([string]$pathProperty.Value)) {
279	        $skipped++
280	        Write-InstallLog -Message "Skipped vault entry without path: $($vaultProperty.Name)"
281	        continue
282	    }
283	
284	    $vaultPath = [string]$pathProperty.Value
285	    if (-not (Test-Path -LiteralPath $vaultPath -PathType Container)) {
286	        $skipped++
287	        Write-InstallLog -Message "Skipped missing vault path: $vaultPath"
288	        continue
289	    }
290	
291	    Install-PluginsForVault -VaultPath $vaultPath -Plugins $pluginDefinitions
292	    $processed++
293	}
294	
295	Write-InstallLog -Message "Finished. Plugins=$($pluginDefinitions.Count); processed vaults=$processed; skipped entries=$skipped."
