55	function Get-PluginsSignature {
56	    $parts = New-Object System.Collections.Generic.List[string]
57	
58	    if (Test-Path -LiteralPath $communityPluginsPath -PathType Leaf) {
59	        $item = Get-Item -LiteralPath $communityPluginsPath
60	        $parts.Add("community:$($item.Length):$($item.LastWriteTimeUtc.Ticks)")
61	    }
62	    else {
63	        $parts.Add('community:missing')
64	    }
65	
66	    if (Test-Path -LiteralPath $pluginsRoot -PathType Container) {
67	        $manifests = Get-ChildItem -LiteralPath $pluginsRoot -Directory -ErrorAction SilentlyContinue |
68	            ForEach-Object {
69	                $manifest = Join-Path $_.FullName 'manifest.json'
70	                if (Test-Path -LiteralPath $manifest -PathType Leaf) {
71	                    Get-Item -LiteralPath $manifest
72	                }
73	            } |
74	            Sort-Object FullName
75	
76	        foreach ($manifest in $manifests) {
77	            $parts.Add("manifest:$($manifest.FullName):$($manifest.Length):$($manifest.LastWriteTimeUtc.Ticks)")
78	        }
79	    }
80	    else {
81	        $parts.Add('plugins:missing')
82	    }
83	
84	    return ($parts -join '|')
85	}
