276	function processPlugin(pid, state) {
277	  const manifestPath = path.join(pluginDir, pid, 'manifest.json');
278	  const manifest = safeReadJson(manifestPath);
279	  if (!manifest) return { status: 'skipped', reason: 'missing-manifest', pluginId: pid };
