282	  const baseName = sanitizeName(manifest.name || pid);
283	  const folderName = baseName;
284	  const folderPath = path.join(outDir, folderName);
285	  const category = inferCategory(manifest);
286	  const type = inferType(manifest, category);
287	  const stateKey = pid;
288	  const previous = state.processed[stateKey];
289	  const version = manifest.version || 'unknown';
290	  const manifestMtime = fs.statSync(manifestPath).mtimeMs;
291	  const docsPresent = hasRequiredDocs(folderPath, baseName, type, pid);
292	  const changed = fullRebuild || !previous || previous.version !== version || previous.folderName !== folderName || !docsPresent;
293	
294	  if (forceRefresh) {
295	    return { status: 'skipped', reason: 'refresh-only', pluginId: pid, folderName };
296	  }
297	
298	  if (!changed) {
299	    return { status: 'unchanged', pluginId: pid, folderName };
300	  }
301	
302	  ensureDir(folderPath);
303	  const guideFile = path.join(folderPath, `${baseName}插件使用指南.md`);
304	  const cheatFile = path.join(folderPath, `${baseName}插件速查表.md`);
