310	  fs.writeFileSync(thirdFile, thirdContent(folderName, baseName, manifest, data, type), 'utf8');
311	
312	  state.processed[stateKey] = {
313	    pluginId: pid,
314	    name: manifest.name || pid,
315	    folderName,
316	    version,
317	    category,
318	    type,
319	    manifestMtime,
320	    updatedAt: new Date().toISOString()
321	  };
322	
323	  return { status: previous ? 'updated' : 'created', pluginId: pid, folderName, version };
324	}
