269	function Should-NotifyTask {
270	    param(
271	        [Parameter(Mandatory = $true)]$Task,
272	        [Parameter(Mandatory = $true)]$TaskState,
273	        [Parameter(Mandatory = $true)]$Plan,
274	        [Parameter(Mandatory = $true)][datetime]$Now
275	    )
276	
277	    $taskTime = Get-TimeInfo -Time ([string]$Task.time)
278	    if ($null -eq $taskTime) {
279	        return $false
280	    }
281	
282	    $currentMinutes = ($Now.Hour * 60) + $Now.Minute
283	    if ($currentMinutes -lt $taskTime.TotalMinutes) {
284	        return $false
285	    }
286	
287	    if ($TaskState.status -eq 'done') {
288	        return $false
289	    }
290	
291	    if ($TaskState.snoozeUntil) {
292	        try {
293	            $snoozeUntil = [datetime]$TaskState.snoozeUntil
294	            if ($Now -lt $snoozeUntil) {
295	                return $false
296	            }
297	        }
298	        catch {
299	        }
300	    }
301	
302	    $maxNotifyCount = if ($Plan.PSObject.Properties['maxNotifyCount']) { [int]$Plan.maxNotifyCount } else { 4 }
303	    $notifyCount = if ($TaskState.notifyCount) { [int]$TaskState.notifyCount } else { 0 }
304	    if ($notifyCount -ge $maxNotifyCount) {
305	        return $false
306	    }
307	
308	    if (-not $TaskState.lastNotifiedAt) {
309	        return $true
310	    }
311	
312	    try {
313	        $last = [datetime]$TaskState.lastNotifiedAt
314	        $repeatMinutes = @($Plan.repeatMinutes)
315	        if ($notifyCount -lt $repeatMinutes.Count) {
316	            $delay = [int]$repeatMinutes[$notifyCount]
317	        }
318	        else {
319	            $delay = [int]$repeatMinutes[-1]
320	        }
321	        return $Now -ge $last.AddMinutes($delay)
322	    }
323	    catch {
324	        return $true
325	    }
326	}
