341	    if ($null -eq $Text) {
342	        return ''
343	    }
344	
345	    $builder = New-Object System.Text.StringBuilder
346	    foreach ($char in $Text.ToCharArray()) {
347	        $code = [int][char]$char
348	        switch ($char) {
349	            '&' { [void]$builder.Append('&amp;') }
350	            '<' { [void]$builder.Append('&lt;') }
351	            '>' { [void]$builder.Append('&gt;') }
352	            '"' { [void]$builder.Append('&quot;') }
353	            "'" { [void]$builder.Append('&#39;') }
354	            "`r" { }
355	            "`n" { [void]$builder.Append('<br/>') }
356	            default {
357	                if ($code -lt 128) {
358	                    [void]$builder.Append($char)
359	                }
360	                else {
361	                    [void]$builder.Append('&#').Append($code).Append(';')
362	                }
363	            }
364	        }
365	    }
