385	function shiftTime(timeText, deltaMinutes) {
386	  const match = String(timeText || '').match(/^(\d{1,2}):(\d{2})$/);
387	  if (!match) return timeText || '08:30';
388	  const hours = Number(match[1]);
389	  const minutes = Number(match[2]);
390	  let total = hours * 60 + minutes + deltaMinutes;
391	  if (total < 0) total = 0;
392	  const nextHours = String(Math.floor(total / 60)).padStart(2, '0');
393	  const nextMinutes = String(total % 60).padStart(2, '0');
394	  return `${nextHours}:${nextMinutes}`;
395	}
