397	function compareTimes(left, right) {
398	  const toMinutes = value => {
399	    const match = String(value || '').match(/^(\d{1,2}):(\d{2})$/);
400	    if (!match) return Number.MAX_SAFE_INTEGER;
401	    return Number(match[1]) * 60 + Number(match[2]);
402	  };
403	  return toMinutes(left) - toMinutes(right);
404	}
