523	function Invoke-NotifierIteration {
524	    $plan = Load-NotificationPlan
525	    $state = Load-State
526	    Ensure-StateShape -State $state
527	    $now = Get-Date
528	    $taskCount = @($plan.tasks).Count
529	    Write-DebugTrace -Message "iteration now=$($now.ToString('o')) tasks=$taskCount"
530	
531	    foreach ($task in @($plan.tasks)) {
532	        $taskKey = Get-TaskStateKey -Task $task
533	        if (-not $state.tasks.ContainsKey($taskKey)) {
534	            $state.tasks[$taskKey] = @{ notifyCount = 0; lastNotifiedAt = ''; status = 'pending'; snoozeUntil = ''; taskId = [string]$task.id; title = [string]$task.title; time = [string]$task.time }
535	        }
536	        $taskState = $state.tasks[$taskKey]
537	        $shouldNotify = Should-NotifyTask -Task $task -TaskState $taskState -Plan $plan -Now $now
538	        Write-DebugTrace -Message "task-check id=$($task.id) key=$taskKey time=$($task.time) shouldNotify=$shouldNotify"
539	        if ($shouldNotify) {
540	            Send-SystemTaskNotification -Task $task -Plan $plan
541	            Update-TaskState -State $state -Task $task -Now $now
542	        }
543	    }
544	
545	    $state.lastRunAt = $now.ToString('o')
546	    Save-State -State $state
