766	function Invoke-NotifierIteration {
767	    $plan = Load-NotificationPlan
768	    $state = Load-State
769	    Ensure-StateShape -State $state
770	    $now = Get-Date
771	    $taskCount = @($plan.tasks).Count
772	    $cleanedStateCount = Remove-StaleTaskState -State $state -Plan $plan -Now $now
773	    Write-DebugTrace -Message "iteration now=$($now.ToString('o')) tasks=$taskCount cleanedState=$cleanedStateCount"
774	
775	    $dueTasks = New-Object System.Collections.Generic.List[object]
776	    foreach ($task in @($plan.tasks)) {
777	        $taskKey = Get-TaskStateKey -Task $task
778	        if (-not $state.tasks.ContainsKey($taskKey)) {
779	            $state.tasks[$taskKey] = @{ notifyCount = 0; lastNotifiedAt = ''; status = 'pending'; snoozeUntil = ''; taskId = [string]$task.id; title = [string]$task.title; time = [string]$task.time }
780	        }
781	        $taskState = $state.tasks[$taskKey]
782	        $shouldNotify = Should-NotifyTask -Task $task -TaskState $taskState -Plan $plan -Now $now
783	        Write-DebugTrace -Message "task-check id=$($task.id) key=$taskKey time=$($task.time) priority=$(Get-TaskPriority -Task $task) shouldNotify=$shouldNotify"
784	        if ($shouldNotify) {
785	            $displayRank = Get-TaskDisplayRank -Task $task -TaskState $taskState -Now $now
786	            $dueTasks.Add([pscustomobject]@{
787	                Task = $task
788	                TaskState = $taskState
789	                DisplayRank = $displayRank
790	            }) | Out-Null
791	        }
792	    }
793	
794	    foreach ($entry in @($dueTasks | Sort-Object @{ Expression = { $_.DisplayRank.PriorityOrder } }, @{ Expression = { $_.DisplayRank.FreshnessBucket } }, @{ Expression = { $_.DisplayRank.OverdueBucket } }, @{ Expression = { $_.DisplayRank.DisplayBias } }, @{ Expression = { $_.DisplayRank.TimeMinutes } })) {
795	        Write-DebugTrace -Message "notify-order id=$($entry.Task.id) priority=$($entry.DisplayRank.Priority) rank=$($entry.DisplayRank.PriorityOrder)/$($entry.DisplayRank.FreshnessBucket)/$($entry.DisplayRank.OverdueBucket)/$($entry.DisplayRank.DisplayBias)"
796	        Send-SystemTaskNotification -Task $entry.Task -Plan $plan -DisplayRank $entry.DisplayRank
797	        Update-TaskState -State $state -Task $entry.Task -Now $now
798	    }
799	
800	    $state.lastRunAt = $now.ToString('o')
801	    Save-State -State $state
802	}
