481	function Should-NotifyTask {
482	    param(
483	        [Parameter(Mandatory = $true)]$Task,
484	        [Parameter(Mandatory = $true)]$TaskState,
485	        [Parameter(Mandatory = $true)]$Plan,
486	        [Parameter(Mandatory = $true)][datetime]$Now
487	    )
488	
489	    $taskTime = Get-TimeInfo -Time ([string]$Task.time)
490	    if ($null -eq $taskTime) {
491	        return $false
492	    }
493	
494	    $currentMinutes = ($Now.Hour * 60) + $Now.Minute
495	    if ($currentMinutes -lt $taskTime.TotalMinutes) {
496	        return $false
497	    }
498	
499	    if ($TaskState.status -eq 'done') {
500	        return $false
501	    }
502	
503	    if ($TaskState.snoozeUntil) {
504	        try {
505	            $snoozeUntil = [datetime]$TaskState.snoozeUntil
506	            if ($Now -lt $snoozeUntil) {
507	                return $false
508	            }
509	        }
510	        catch {
511	        }
512	    }
513	
514	    $maxNotifyCount = if ($Plan.PSObject.Properties['maxNotifyCount']) { [int]$Plan.maxNotifyCount } else { 4 }
515	    $notifyCount = if ($TaskState.notifyCount) { [int]$TaskState.notifyCount } else { 0 }
516	    if ($notifyCount -ge $maxNotifyCount) {
517	        return $false
518	    }
519	
520	    if (-not $TaskState.lastNotifiedAt) {
521	        return $true
522	    }
523	
524	    try {
525	        $last = [datetime]$TaskState.lastNotifiedAt
526	        $repeatMinutes = @($Plan.repeatMinutes)
527	        if ($notifyCount -lt $repeatMinutes.Count) {
528	            $delay = [int]$repeatMinutes[$notifyCount]
529	        }
530	        else {
531	            $delay = [int]$repeatMinutes[-1]
532	        }
533	        return $Now -ge $last.AddMinutes($delay)
534	    }
535	    catch {
536	        return $true
537	    }
538	}
