461	            }
462	            try {
463	                $referenceTime = [datetime]$candidate
464	                break
465	            }
466	            catch {
467	            }
468	        }
469	
470	        if ($null -eq $referenceTime -or $referenceTime -le $Now.AddDays(-1)) {
471	            $keysToRemove.Add($stateKey) | Out-Null
472	        }
473	    }
474	
475	    foreach ($stateKey in $keysToRemove) {
