550	function Convert-ToHtmlEntityString {
551	    param([AllowNull()][string]$Text)
552	
553	    if ($null -eq $Text) {
554	        return ''
555	    }
556	
557	    $builder = New-Object System.Text.StringBuilder
558	    foreach ($char in $Text.ToCharArray()) {
559	        $code = [int][char]$char
560	        switch ($char) {
561	            '&' { [void]$builder.Append('&amp;') }
562	            '<' { [void]$builder.Append('&lt;') }
563	            '>' { [void]$builder.Append('&gt;') }
564	            '"' { [void]$builder.Append('&quot;') }
565	            "'" { [void]$builder.Append('&#39;') }
566	            "`r" { }
567	            "`n" { [void]$builder.Append('<br/>') }
568	            default {
569	                if ($code -lt 128) {
570	                    [void]$builder.Append($char)
571	                }
572	                else {
573	                    [void]$builder.Append('&#').Append($code).Append(';')
574	                }
575	            }
576	        }
577	    }
578	    return $builder.ToString()
579	}
