652	function Send-SystemTaskNotification {
653	    param(
654	        [Parameter(Mandatory = $true)]$Task,
655	        [Parameter(Mandatory = $true)]$Plan,
656	        [Parameter(Mandatory = $true)]$DisplayRank
657	    )
658	
659	    $priority = Get-TaskPriority -Task $Task
660	    $visualSpec = Get-PriorityVisualSpec -Priority $priority
661	    $title = '当前任务提醒'
662	    $taskTimeText = [string]$Task.time
663	    $taskTitleText = [string]$Task.title
664	    $message = "[$taskTimeText] $taskTitleText"
665	    $fullMessage = $message
666	    $usedFallback = $false
667	    $toastShown = $false
668	    $popupLaunched = $false
669	
670	    try {
671	        if ($Plan.enableToast) {
672	            [Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime] > $null
673	            [Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom.XmlDocument, ContentType = WindowsRuntime] > $null
674	            $toastTitle = switch ($priority) {
675	                'important-urgent' { '【重要紧急】当前任务提醒' }
676	                'important-not-urgent' { '【重要】当前任务提醒' }
677	                'recurring' { '【持续任务】当前任务提醒' }
678	                'test' { '【测试】当前任务提醒' }
679	                default { $title }
680	            }
681	            $toastPrefix = switch ($priority) {
682	                'important-urgent' { '请立即处理：' }
683	                'important-not-urgent' { '优先安排：' }
684	                'recurring' { '保持节奏：' }
685	                'test' { '验证提醒链路：' }
686	                default { '' }
687	            }
688	            $toastBody = if ([string]::IsNullOrWhiteSpace($toastPrefix)) { $fullMessage } else { "$toastPrefix$fullMessage" }
689	            $escapedTitle = [System.Security.SecurityElement]::Escape($toastTitle)
690	            $escapedMessage = [System.Security.SecurityElement]::Escape($toastBody)
691	            $xmlText = @"
692	<toast>
693	  <visual>
694	    <binding template="ToastGeneric">
695	      <text>$escapedTitle</text>
696	      <text>$escapedMessage</text>
697	    </binding>
698	  </visual>
699	  <audio src="ms-winsoundevent:Notification.Looping.Alarm2"/>
700	</toast>
701	"@
702	            $xml = New-Object Windows.Data.Xml.Dom.XmlDocument
703	            $xml.LoadXml($xmlText)
704	            $toast = [Windows.UI.Notifications.ToastNotification]::new($xml)
705	            [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier('Obsidian Task Notifier').Show($toast)
706	            $toastShown = $true
707	            Write-DebugTrace -Message "toast-show invoked priority=$priority"
708	        }
709	        else {
710	            $usedFallback = $true
711	            Write-DebugTrace -Message 'toast-disabled use-fallback'
712	        }
713	    }
714	    catch {
715	        $usedFallback = $true
716	        Write-DebugTrace -Message "toast-failed reason=$($_.Exception.Message)"
717	        Write-RunLog -Message "toast failed title=$($Task.title) reason=$($_.Exception.Message)"
718	    }
719	
720	    if ($Plan.enableSound) {
721	        Play-AlertSound
722	    }
723	
724	    if ($Plan.enableFallbackPopup) {
725	        $usedFallback = $true
726	        $popupLaunched = Show-FallbackPopup -Title $title -Message $fullMessage -VisualSpec $visualSpec
727	    }
728	
729	    Write-RunLog -Message "notify time=$($Task.time) title=$($Task.title) priority=$priority displayOrder=$($DisplayRank.PriorityOrder)/$($DisplayRank.FreshnessBucket)/$($DisplayRank.OverdueBucket) fallback=$usedFallback toastShown=$toastShown popupLaunched=$popupLaunched"
730	}
