804	function Enter-NotifierMutex {
805	    $createdNew = $false
806	    $mutexInstance = New-Object System.Threading.Mutex($true, 'Local\ObsidianSystemTaskNotifier', [ref]$createdNew)
807	    return [pscustomobject]@{
808	        Mutex = $mutexInstance
809	        CreatedNew = $createdNew
810	    }
811	}
812	
813	if ($CleanTestState) {
814	    $mutexInfo = Enter-NotifierMutex
815	    if (-not $mutexInfo.CreatedNew) {
816	        Write-DebugTrace -Message 'manual-clean waiting-for-running-notifier'
817	        $null = $mutexInfo.Mutex.WaitOne(15000)
818	    }
819	    try {
820	        $plan = Load-NotificationPlan
821	        $state = Load-State
822	        Ensure-StateShape -State $state
823	        $removedCount = Remove-StaleTaskState -State $state -Plan $plan -Now (Get-Date) -Force
824	        Save-State -State $state
825	        Write-RunLog -Message "manual clean test state removed=$removedCount"
826	        Write-DebugTrace -Message "manual-clean-test-state removed=$removedCount"
827	    }
828	    finally {
829	        if ($null -ne $mutexInfo.Mutex) {
830	            try { $mutexInfo.Mutex.ReleaseMutex() | Out-Null } catch {}
831	            $mutexInfo.Mutex.Dispose()
832	        }
833	    }
834	    exit 0
835	}
836	
837	if ($TestToast) {
838	    $plan = [pscustomobject]@{ enableToast = $true; enableSound = $true; enableFallbackPopup = $true }
839	    $task = [pscustomobject]@{ time = (Get-Date).AddMinutes(1).ToString('HH:mm'); title = '系统提醒测试'; sourceFile = Get-TodayTodoPath; priority = 'test' }
840	    $displayRank = Get-TaskDisplayRank -Task $task -TaskState @{ lastNotifiedAt = '' } -Now (Get-Date)
841	    Send-SystemTaskNotification -Task $task -Plan $plan -DisplayRank $displayRank
842	    exit 0
843	}
844	
845	$mutexInfo = Enter-NotifierMutex
846	$mutex = $mutexInfo.Mutex
847	$createdNew = [bool]$mutexInfo.CreatedNew
848	if (-not $createdNew) {
849	    Write-RunLog -Message 'System task notifier is already running; exiting duplicate instance.'
850	    Write-DebugTrace -Message 'mutex-duplicate-exit'
851	    exit 0
852	}
853	
854	try {
855	    Write-RunLog -Message "System task notifier started. RunOnce=$RunOnce PollSeconds=$PollSeconds"
856	    do {
857	        Invoke-NotifierIteration
858	        if (-not $RunOnce) {
859	            Start-Sleep -Seconds $PollSeconds
860	        }
861	    } while (-not $RunOnce)
862	}
863	catch {
864	    Write-RunLog -Message "System task notifier failed: $($_.Exception.Message)"
865	    throw
866	}
867	finally {
868	    if ($null -ne $mutex) {
869	        $mutex.ReleaseMutex() | Out-Null
870	        $mutex.Dispose()
871	    }
872	}
