579	function Should-NotifyTask {
580	    param(
581	        [Parameter(Mandatory = $true)]$Task,
582	        [Parameter(Mandatory = $true)]$TaskState,
583	        [Parameter(Mandatory = $true)]$Plan,
584	        [Parameter(Mandatory = $true)][datetime]$Now
585	    )
586	
587	    $taskTime = Get-TimeInfo -Time ([string]$Task.time)
588	    if ($null -eq $taskTime) {
589	        return $false
590	    }
591	
592	    $currentMinutes = ($Now.Hour * 60) + $Now.Minute
593	    if ($currentMinutes -lt $taskTime.TotalMinutes) {
594	        return $false
595	    }
596	
597	    if ($TaskState.status -eq 'done') {
598	        return $false
599	    }
600	
601	    if ($TaskState.snoozeUntil) {
602	        try {
603	            $snoozeUntil = [datetime]$TaskState.snoozeUntil
604	            if ($Now -lt $snoozeUntil) {
605	                return $false
606	            }
607	        }
608	        catch {
609	        }
610	    }
611	
612	    $maxNotifyCount = if ($Plan.PSObject.Properties['maxNotifyCount']) { [int]$Plan.maxNotifyCount } else { 4 }
613	    $notifyCount = if ($TaskState.notifyCount) { [int]$TaskState.notifyCount } else { 0 }
614	    if ($notifyCount -ge $maxNotifyCount) {
615	        return $false
616	    }
617	
618	    if (-not $TaskState.lastNotifiedAt) {
619	        return $true
620	    }
621	
622	    try {
623	        $last = [datetime]$TaskState.lastNotifiedAt
624	        $repeatMinutes = @($Plan.repeatMinutes)
625	        if ($notifyCount -lt $repeatMinutes.Count) {
626	            $delay = [int]$repeatMinutes[$notifyCount]
627	        }
628	        else {
629	            $delay = [int]$repeatMinutes[-1]
630	        }
631	        return $Now -ge $last.AddMinutes($delay)
632	    }
633	    catch {
634	        return $true
635	    }
636	}
