648	function Convert-ToHtmlEntityString {
649	    param([AllowNull()][string]$Text)
650	
651	    if ($null -eq $Text) {
652	        return ''
653	    }
654	
655	    $builder = New-Object System.Text.StringBuilder
656	    foreach ($char in $Text.ToCharArray()) {
657	        $code = [int][char]$char
658	        switch ($char) {
659	            '&' { [void]$builder.Append('&amp;') }
660	            '<' { [void]$builder.Append('&lt;') }
661	            '>' { [void]$builder.Append('&gt;') }
662	            '"' { [void]$builder.Append('&quot;') }
663	            "'" { [void]$builder.Append('&#39;') }
664	            "`r" { }
665	            "`n" { [void]$builder.Append('<br/>') }
666	            default {
667	                if ($code -lt 128) {
668	                    [void]$builder.Append($char)
669	                }
670	                else {
671	                    [void]$builder.Append('&#').Append($code).Append(';')
672	                }
673	            }
674	        }
675	    }
676	    return $builder.ToString()
677	}
