563	function Format-RemainingTasksSummary {
564	    param(
565	        [Parameter(Mandatory = $true)]$CurrentTask,
566	        [Parameter(Mandatory = $true)]$RemainingTasks,
567	        [Parameter(Mandatory = $true)][datetime]$Now,
568	        [int]$MaxItems = 5
569	    )
570	
571	    $overdueStartMarker = '__OVERDUE_START__'
572	    $overdueEndMarker = '__OVERDUE_END__'
573	    $lines = New-Object System.Collections.Generic.List[string]
574	    $lines.Add('当前任务：') | Out-Null
575	    $lines.Add((Get-TaskSummaryLine -Task $CurrentTask -MaxTitleLength 0)) | Out-Null
576	    $lines.Add('') | Out-Null
577	    $lines.Add('当天剩余未完成任务：') | Out-Null
578	
579	    $remainingCount = @($RemainingTasks).Count
580	    if ($remainingCount -le 0) {
581	        $lines.Add('今天其余任务已完成。') | Out-Null
582	        return ($lines -join "`n")
583	    }
584	
585	    $displayCount = [Math]::Min($MaxItems, $remainingCount)
586	    for ($i = 0; $i -lt $displayCount; $i++) {
587	        $task = @($RemainingTasks)[$i]
588	        $line = "• $(Get-TaskSummaryLine -Task $task)"
589	        if (Test-TaskOverdue -Task $task -Now $Now) {
590	            $line = "$overdueStartMarker$line$overdueEndMarker"
591	        }
592	        $lines.Add($line) | Out-Null
593	    }
