602	function Should-NotifyTask {
603	    param(
604	        [Parameter(Mandatory = $true)]$Task,
605	        [Parameter(Mandatory = $true)]$TaskState,
606	        [Parameter(Mandatory = $true)]$Plan,
607	        [Parameter(Mandatory = $true)][datetime]$Now
608	    )
609	
610	    $taskTime = Get-TimeInfo -Time ([string]$Task.time)
611	    if ($null -eq $taskTime) {
612	        return $false
613	    }
614	
615	    $currentMinutes = ($Now.Hour * 60) + $Now.Minute
616	    if ($currentMinutes -lt $taskTime.TotalMinutes) {
617	        return $false
618	    }
619	
620	    if ($TaskState.status -eq 'done') {
621	        return $false
622	    }
623	
624	    if ($TaskState.snoozeUntil) {
625	        try {
626	            $snoozeUntil = [datetime]$TaskState.snoozeUntil
627	            if ($Now -lt $snoozeUntil) {
628	                return $false
629	            }
630	        }
631	        catch {
632	        }
633	    }
634	
635	    $maxNotifyCount = if ($Plan.PSObject.Properties['maxNotifyCount']) { [int]$Plan.maxNotifyCount } else { 4 }
636	    $notifyCount = if ($TaskState.notifyCount) { [int]$TaskState.notifyCount } else { 0 }
637	    if ($notifyCount -ge $maxNotifyCount) {
638	        return $false
639	    }
640	
641	    if (-not $TaskState.lastNotifiedAt) {
642	        return $true
643	    }
644	
645	    try {
646	        $last = [datetime]$TaskState.lastNotifiedAt
647	        $repeatMinutes = @($Plan.repeatMinutes)
648	        if ($notifyCount -lt $repeatMinutes.Count) {
649	            $delay = [int]$repeatMinutes[$notifyCount]
650	        }
651	        else {
652	            $delay = [int]$repeatMinutes[-1]
653	        }
654	        return $Now -ge $last.AddMinutes($delay)
655	    }
656	    catch {
657	        return $true
658	    }
659	}
