146	function Get-DayPlannerTasksFromMarkdown {
147	    $todayFile = Get-TodayTodoPath
148	    if (-not (Test-Path -LiteralPath $todayFile -PathType Leaf)) {
149	        return @()
150	    }
151	
152	    $raw = Get-Content -Raw -LiteralPath $todayFile
153	    $normalized = $raw -replace "`r`n", "`n"
154	    $match = [regex]::Match($normalized, '## Day Planner 今日安排\n\n([\s\S]*?)(?=\n## |$)')
155	    if (-not $match.Success) {
156	        return @()
157	    }
158	
159	    $lines = $match.Groups[1].Value -split "`n"
160	    $tasks = New-Object System.Collections.Generic.List[object]
161	    $lineIndex = 0
162	    foreach ($line in $lines) {
163	        $lineIndex++
164	        $trimmed = $line.Trim()
165	        if ($trimmed -match '^- \[[ x/\-]\]\s*(\d{2}:\d{2})\s+(.+)$') {
166	            $time = $matches[1]
167	            $title = $matches[2]
168	            $tasks.Add([pscustomobject]@{
169	                id = "fallback_$time`_$lineIndex"
170	                planDate = (Get-Date -Format 'yyyy-MM-dd')
171	                time = $time
172	                title = $title
173	                sourceFile = $todayFile
174	                sourceLine = $lineIndex
175	                rawText = $trimmed
176	                priority = Get-TaskPriority -Task ([pscustomobject]@{ title = $title })
177	                status = 'pending'
178	                notifyCount = 0
179	                lastNotifiedAt = ''
180	                snoozeUntil = ''
181	            }) | Out-Null
182	        }
183	    }
184	    return @($tasks)
185	}
