243	function Get-TaskStateKey {
244	    param([Parameter(Mandatory = $true)]$Task)
245	
246	    $idText = [string]$Task.id
247	    if ([string]::IsNullOrWhiteSpace($idText)) {
248	        return [guid]::NewGuid().ToString('N')
249	    }
250	
251	    $bytes = [System.Text.Encoding]::UTF8.GetBytes($idText)
252	    $hashBytes = [System.Security.Cryptography.SHA256]::Create().ComputeHash($bytes)
253	    $hash = [System.BitConverter]::ToString($hashBytes).Replace('-', '').ToLowerInvariant()
254	    return "task_$hash"
255	}
