257	function Get-TimeInfo {
258	    param([Parameter(Mandatory = $true)][string]$Time)
259	    if ($Time -notmatch '^(\d{2}):(\d{2})$') {
260	        return $null

680	        $code = [int][char]$char
681	        switch ($char) {
682	            '&' { [void]$builder.Append('&amp;') }
683	            '<' { [void]$builder.Append('&lt;') }
684	            '>' { [void]$builder.Append('&gt;') }
685	            '"' { [void]$builder.Append('&quot;') }
686	            "'" { [void]$builder.Append('&#39;') }
687	            "`r" { }
688	            "`n" { [void]$builder.Append('<br/>') }
689	            default {
690	                if ($code -lt 128) {
691	                    [void]$builder.Append($char)
692	                }
693	                else {
694	                    [void]$builder.Append('&#').Append($code).Append(';')
695	                }
696	            }
697	        }
698	    }
699	    return $builder.ToString()
700	}
