105	  buildNotificationPlan(content, sourceFile) {
106	    const planDate = this.formatDate(new Date());
107	    const section = this.extractPlannerSection(content || '');
108	    const lines = section.split(/\r?\n/).filter(Boolean);
109	    const tasks = lines
110	      .map((line, index) => this.parsePlannerLine(line, index + 1, sourceFile, planDate))
111	      .filter(Boolean);
112	
113	    return {
114	      planDate,
115	      sourceFile,
116	      tasks: this.normalizeTasks(tasks)
117	    };
118	  }
119	
120	  extractPlannerSection(content) {
121	    const heading = this.settings.plannerHeading || DEFAULT_SETTINGS.plannerHeading;
122	    const escaped = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
123	    const regex = new RegExp(`${escaped}\\n\\n([\\s\\S]*?)(?=\\n## |$)`);
124	    const match = String(content || '').replace(/\r\n/g, '\n').match(regex);
125	    return match ? match[1].trimEnd() : '';
126	  }
127	
128	  parsePlannerLine(line, sourceLine, sourceFile, planDate) {
129	    const normalized = String(line || '').trim();
130	    const match = normalized.match(/^- \[[ x\/\-]\]\s*(\d{2}:\d{2})\s+(.+)$/);
131	    if (!match) return null;
132	    const [, time, title] = match;
133	    return {
134	      id: `${planDate}_${time}_${sourceLine}_${this.slugify(title)}`,
135	      planDate,
136	      time,
137	      title: title.trim(),
138	      sourceFile,
139	      sourceLine,
140	      rawText: normalized,
141	      priority: this.detectPriority(title),
142	      status: 'pending',
143	      notifyCount: 0,
144	      lastNotifiedAt: '',
145	      snoozeUntil: ''
146	    };
147	  }
148	
149	  detectPriority(title) {
150	    if (/重要紧急/.test(title)) return 'important-urgent';
151	    if (/重要不紧急/.test(title)) return 'important-not-urgent';
152	    if (/持续/.test(title)) return 'recurring';
153	    return 'normal';
154	  }
155	
156	  normalizeTasks(tasks) {
157	    const seen = new Set();
158	    return (tasks || []).filter(task => {
159	      if (!task || !task.id) return false;
160	      if (seen.has(task.id)) return false;
161	      seen.add(task.id);
162	      return true;
163	    });
164	  }
165	
166	  createTestTask() {
167	    const now = new Date();
168	    now.setMinutes(now.getMinutes() + 1);
169	    now.setSeconds(0, 0);
170	    const planDate = this.formatDate(now);
171	    const time = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
172	    const title = '系统提醒测试任务（1分钟后）';
173	    return {
174	      id: `${planDate}_${time}_test_${Date.now()}`,
175	      planDate,
176	      time,
177	      title,
178	      sourceFile: this.resolveTodayNotePath(),
179	      sourceLine: 0,
180	      rawText: `- [ ] ${time} ${title}`,
181	      priority: 'test',
182	      status: 'pending',
183	      notifyCount: 0,
184	      lastNotifiedAt: '',
185	      snoozeUntil: ''
186	    };
187	  }
188	
189	  resolveTodayNotePath() {
190	    const vaultPath = this.app.vault.adapter.basePath;
191	    const fileName = `${this.formatDate(new Date())}-今日待办.md`;
192	    return path.join(vaultPath, this.settings.todoFolder || DEFAULT_SETTINGS.todoFolder, fileName);
193	  }
194	
195	  formatDate(date) {
196	    const y = date.getFullYear();
197	    const m = String(date.getMonth() + 1).padStart(2, '0');
198	    const d = String(date.getDate()).padStart(2, '0');
199	    return `${y}-${m}-${d}`;
200	  }
201	
202	  slugify(text) {
203	    const normalized = String(text || '')
204	      .toLowerCase()
205	      .replace(/ai/g, 'ai')
206	      .replace(/学习obsidian/g, 'study-obsidian')
207	      .replace(/学习更多ai知识/g, 'learn-more-ai')
208	      .replace(/驱动工作流/g, 'workflow-drive');
209	
210	    const ascii = normalized
211	      .replace(/[^a-z0-9]+/g, '-')
212	      .replace(/^-+|-+$/g, '');
213	
214	    return (ascii || 'task').slice(0, 48);
215	  }
