426	function Remove-StaleTaskState {
427	    param(
428	        [Parameter(Mandatory = $true)]$State,
429	        [Parameter(Mandatory = $true)]$Plan,
430	        [Parameter(Mandatory = $true)][datetime]$Now,
431	        [switch]$Force
432	    )
433	
434	    $activeTaskIds = @{}
435	    foreach ($planTask in @($Plan.tasks)) {
436	        $activeTaskIds[[string]$planTask.id] = $true
437	    }
438	
439	    $keysToRemove = New-Object System.Collections.Generic.List[string]
440	    foreach ($stateKey in @($State.tasks.Keys)) {
441	        $entry = $State.tasks[$stateKey]
442	        $taskId = if ($entry.PSObject.Properties.Name -contains 'taskId' -and $entry.taskId) { [string]$entry.taskId } else { [string]$stateKey }
443	        $title = if ($entry.PSObject.Properties.Name -contains 'title' -and $entry.title) { [string]$entry.title } else { '' }
444	        $isTestRecord = ($taskId -match '_test_' -or $stateKey -match '_test_' -or $title -match '测试')
445	        if (-not $isTestRecord) {
446	            continue
447	        }
448	        if ($activeTaskIds.ContainsKey($taskId)) {
449	            continue
450	        }
451	
452	        if ($Force) {
453	            $keysToRemove.Add($stateKey) | Out-Null
454	            continue
455	        }
456	
457	        $referenceTime = $null
458	        foreach ($candidate in @([string]$entry.lastNotifiedAt, [string]$State.lastRunAt)) {
459	            if ([string]::IsNullOrWhiteSpace($candidate)) {
460	                continue
461	            }
462	            try {
463	                $referenceTime = [datetime]$candidate
464	                break
465	            }
466	            catch {
467	            }
468	        }
469	
470	        if ($null -eq $referenceTime -or $referenceTime -le $Now.AddDays(-1)) {
471	            $keysToRemove.Add($stateKey) | Out-Null
472	        }
473	    }
474	
475	    foreach ($stateKey in $keysToRemove) {
476	        $State.tasks.Remove($stateKey)
477	    }
478	    return $keysToRemove.Count
479	}
